"""Render a bounded calibration result from verified compact files."""
import json,hashlib
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1]
def main():
 r=ROOT/'results/gate_calibration';status=json.loads((r/'status.json').read_text());native=r/'native_completed';out=native/'output'/f"job_{status['job']}"
 audit=json.loads((out/'independent_audit.json').read_text());summary=json.loads((out/'summary.json').read_text());selection=json.loads((out/'selection_lock.json').read_text());receipt=json.loads((native/'execution_receipt.json').read_text())
 sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
 assert audit['summary_sha256']==sha(out/'summary.json') and receipt['status']=='COMPLETE_WITH_INDEPENDENT_AUDIT'
 transfer=json.loads((native/'transfer_integrity.json').read_text());assert all(v['native_before_sha256']==v['local_sha256']==v['native_after_sha256'] for v in transfer['files'])
 alpha=audit['selected_alpha'];grid=sorted(map(float,selection['score_by_alpha']));scores=[selection['score_by_alpha'][str(a)] for a in grid]
 plt.rcParams.update({'font.size':11,'axes.spines.top':False,'axes.spines.right':False})
 fig,ax=plt.subplots(1,2,figsize=(10.4,3.7),gridspec_kw={'width_ratios':[1.1,1]})
 ax[0].plot(grid,scores,'o-',color='black');ax[0].scatter([alpha],[selection['score_by_alpha'][str(alpha)]],s=100,facecolors='white',edgecolors='black',zorder=4)
 ax[0].set(xlabel='History correction strength (alpha)',ylabel='Original validation feature MSE',title='A. Choose once on validation',xticks=grid)
 labels=['Feature rule','Task rule','Both rules'];old=[audit['baseline'][k] for k in ('feature','task','both')];new=[audit['selected'][k] for k in ('feature','task','both')];x=np.arange(3)
 ax[1].bar(x-.18,old,.34,color='white',edgecolor='black',label='Original alpha=1');ax[1].bar(x+.18,new,.34,color='.3',edgecolor='black',label=f'Selected alpha={alpha:g}')
 for xx,n in zip(x-.18,old):ax[1].text(xx,n+.7,str(n),ha='center',fontsize=10)
 for xx,n in zip(x+.18,new):ax[1].text(xx,n+.7,str(n),ha='center',fontsize=10)
 ax[1].set(xticks=x,xticklabels=labels,ylim=(0,60),ylabel='Passed checks / 54',title='B. Original deletion rules');ax[1].legend(frameon=False,fontsize=9,loc='upper left')
 fig.tight_layout();f=r/'figures';f.mkdir(exist_ok=True);fig.savefig(f/'gate_calibration.png',dpi=180,bbox_inches='tight');fig.savefig(f/'gate_calibration.pdf',bbox_inches='tight');plt.close(fig)
 table='\n'.join(f'| {a:g} | {selection["score_by_alpha"][str(a)]:.8f} |'+(' <!-- selected -->' if a==alpha else '') for a in grid)
 b=audit['baseline'];n=audit['selected'];bm=audit['baseline_seedmean'];nm=audit['selected_seedmean']
 text=f'''# Gate: one validation-selected calibration\n\n18 October 2026. No network retraining, no new encoding and **zero additional GPU seconds**. All old results and acceptance rules are preserved. This is a scalar calibration on revealed development data, not an independent confirmation.\n\n## Objective and design\n\nThe previous diagnosis found that history can improve the cue-dependent distinction while distorting the full predicted feature. We tested one bounded adjustment:\n\n`prediction = recent-only reference + alpha * (frozen prediction - recent-only reference)`\n\nAlpha = 1 reproduces the original predictor; alpha = 0 removes its history correction. A single Gate value was selected across seeds 17/29/43 by the original equal-condition, equal-horizon full-feature MSE on 96 validation pairs. Four original conditions and both horizons were retained. All five strengths were fixed before this run. Exact validation ties favor the unchanged model. No test result selected the coefficient, and no per-condition or per-seed tuning was allowed. This is one scalar parameter selection, even though no network weight was trained.\n\n## Validation selection\n\n| Alpha | Original validation MSE |\n|---|---:|\n{table}\n\nSelected alpha: **{alpha:g}**. The selection file and validation CSV were hashed before test-fork evaluation began.\n\n![Validation choice and unchanged deletion checks](../results/gate_calibration/figures/gate_calibration.png)\n\nLeft: lower validation MSE is better; the outlined dot is the only selected candidate. Right: numbers count the original 54 individual-seed deletion checks, not scenes, accuracies or independent experiments. Both rules means feature MSE and task-error criteria pass in the same cell. Correlated seeds/positions/horizons are not added as independent samples.\n\n## Deletion results under the original rules\n\n| Original rule | Original alpha = 1 | Selected alpha{alpha:g} |\n|---|---:|---:|\n| Feature error | {b['feature']}/54 | {n['feature']}/54 |\n| Task error | {b['task']}/54 | {n['task']}/54 |\n| Both errors | {b['both']}/54 | {n['both']}/54 |\n| Both errors after averaging seeds within each pair | {bm['both']}/18 | {nm['both']}/18 |\n\nEach check retains the original 10% relative effect and strictly positive paired 95% bootstrap lower bound over 128 base pairs. All three cue positions, three original conditions, three seeds and horizons 3/6 remain. No failed cell was removed. Full-feature error was not replaced by task-weighted loss.\n\n## What this establishes\n\nThe full 41,472 original Gate fork outcomes were replayed. Alpha = 1 feature errors match with maximum difference **{summary['max_original_feature_mse_difference']}**, and original task mismatches are **{summary['original_task_mismatches']}**. Empty-history output still equals the frozen recent reference exactly. An independent process reconstructed the global validation choice and all 72 selected deletion cells (54 individual-seed plus 18 seed-mean), and reproduced the original bootstrap decisions.\n\nThis checks whether shrinking the existing correction repairs deletion utility. It does not rerun all original forecasting/adoption tests, does not establish a deployable past-only retention policy, and cannot establish original Proposal Phase1_GO. Original Motion forecasting failures remain. Fresh 9137 was not generated or opened.\n\n## Decision\n\n'''
 if alpha==0:text+='Validation selected the recent-only endpoint. Removing history can reduce overall feature error, but then deleting a cue has no predictive effect. This calibration therefore does not produce a useful Gate deletion signal; stop this bounded adjustment rather than expand the search.\n'
 elif alpha==1:text+='Validation selected the unchanged predictor: shrinking history increases the registered validation error. The selected candidate is therefore exactly the old model, and its deletion checks remain unchanged. This bounded calibration does not repair Gate. We did not choose a weaker coefficient using test results or expand the grid. The difference between useful validation history and unstable equal-capacity deletion effects points to a validation-to-assay generalization limitation; it does not uniquely identify its mechanism. Original Proposal Phase1_GO and joint Gate-and-Motion policy readiness remain unsupported.\n'
 elif n['both']==54 and nm['both']==18:text+='The age-controlled Gate deletion diagnostic supports the selected correction under its original checks. This is a development result only; full original forecasting prerequisites and Motion must still be independently verified before any confirmation or joint policy-readiness claim.\n'
 else:text+=f"The selected scale changes joint coverage from{b['both']}/54 to{n['both']}/54, and seed-mean coverage from{bm['both']}/18 to{nm['both']}/18. It does not resolve Gate under the unchanged full set of checks. Stop this scalar adjustment; do not tune a second coefficient on these test results. A joint Gate-and-Motion retention-policy readiness claim remains unsupported.\n"
 text+='\n## Reproducible evidence and limitations\n\nThe code and protocol are frozen in `experiments/gate_calibration/`. Compact validation/raw paired metrics, summary, independent audit and native execution receipts are in `results/gate_calibration/native_completed/`; transfer hashes cover native-before, local and native-after copies. Weights and arrays remain on HPC. Selection uses the original validation set but this candidate was motivated by revealed test failures; its subsequent test result is exploratory development evidence, not a fresh unbiased estimate. No GitHub update or retention-policy training was performed.\n'
 (ROOT/'docs/GATE_CALIBRATION_RESULTS.md').write_text(text)
 (r/'readable_results.json').write_text(json.dumps(dict(alpha=alpha,validation_scores=selection['score_by_alpha'],before=b,after=n,before_seedmean=bm,after_seedmean=nm,GPU_seconds_added=0,original_Phase1_GO=False),indent=2)+'\n')
 print(json.dumps(dict(alpha=alpha,before=b,after=n,report='docs/GATE_CALIBRATION_RESULTS.md')))
if __name__=='__main__':main()
